#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <map>
#include <string>
#include <iomanip>
using namespace std;

int main(){
vector<double> oldScore={0.9,0.1,0.8,0.2},newScore={0.9,0.1,0.8,0.2};
vector<int> oldLabel={1,0,1,0},newLabel={0,1,0,1};
auto brier=[](const vector<double>& p,const vector<int>& y){
    double loss=0;
    for(int i=0;i<int(p.size());i++)loss+=pow(p[i]-y[i],2)/p.size();
    return loss;
};
cout<<"Old Brier "<<brier(oldScore,oldLabel)
    <<" new Brier "<<brier(newScore,newLabel)<<endl;
    return 0;
}

