#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <map>
#include <string>
#include <iomanip>
using namespace std;

int main(){
vector<int> confounder={0,0,1,1,1,1};
vector<int> treatment={0,1,0,1,0,1};
vector<double> outcome={2,2.5,7,7.5,8,8.5};
for(int group=0;group<2;group++){
    double control=0,treated=0;int nc=0,nt=0;
    for(int i=0;i<int(confounder.size());i++)
        if(confounder[i]==group){
            if(treatment[i]){treated+=outcome[i];nt++;}
            else{control+=outcome[i];nc++;}
        }
    cout<<"Stratum "<<group<<" difference "<<treated/nt-control/nc<<endl;
}
    return 0;
}

