using namespace std;

int main(){
vector<double> gradients={2,1,-0.5,0.3};
double beta1=0.9,moment=0;
for(int t=1;t<=int(gradients.size());t++){
    moment=beta1*moment+(1-beta1)*gradients[t-1];
