#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <map>
#include <string>
#include <iomanip>
using namespace std;

int main(){
vector<double> market={0.01,-0.02,0.03,0.01,-0.01};
vector<double> asset={0.015,-0.025,0.04,0.005,-0.012};
double meanM=0,meanA=0,numerator=0,denominator=0;
for(int i=0;i<int(market.size());i++){
    meanM+=market[i]/market.size();
    meanA+=asset[i]/asset.size();
}
for(int i=0;i<int(market.size());i++){
    numerator+=(market[i]-meanM)*(asset[i]-meanA);
    denominator+=pow(market[i]-meanM,2);
}
cout<<"Estimated Beta "<<numerator/denominator<<endl;
    return 0;
}

