#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <map>
#include <string>
#include <iomanip>
using namespace std;

int main(){
vector<double> validation={0.15,0.12,0.11,0.13};
vector<int> trainingMinutes={2,4,9,16};
int budgetMinutes=15,spent=0,best=-1;
for(int i=0;i<int(validation.size());i++){
    if(spent+trainingMinutes[i]>budgetMinutes)break;
    spent+=trainingMinutes[i];
    if(best<0||validation[i]<validation[best])best=i;
}
cout<<"Trial "<<best<<" loss "<<validation[best]
    <<" elapsed minutes "<<spent<<endl;
    return 0;
}
